const items = $input.all();
const output = [];

for (const item of items) {
  if (!item.binary) continue;

  for (const [key, value] of Object.entries(item.binary)) {
    const fileName = value.fileName || '';
    const mimeType = value.mimeType || '';

    if (fileName.toLowerCase().endsWith('.pdf') || mimeType === 'application/pdf') {
      const safeFileName = fileName
        .replace(/\s+/g, '_')
        .replace(/[^a-zA-Z0-9._-]/g, '');

      output.push({
        json: {
          ...item.json,
          original_file_name: fileName,
          safe_file_name: safeFileName,
          pdf_url: `https://TU-DOMINIO.com/facturas/${safeFileName}`
        },
        binary: {
          data: {
            ...value,
            fileName: safeFileName
          }
        }
      });
    }
  }
}

return output;

const item = $input.first();

const text = item.json.text || item.json.data || '';

return [
  {
    json: {
      ...item.json,
      raw_text: text,
      pdf_url: item.json.pdf_url || null,
      safe_file_name: item.json.safe_file_name || null,
      original_file_name: item.json.original_file_name || null
    },
    binary: item.binary
  }
];

const original = $('Normalizar texto').first().json;
const ai = $input.first().json;

let factura = null;

if (ai.message?.content) {
  factura = ai.message.content;
} else if (ai.factura) {
  factura = ai.factura;
} else {
  factura = ai;
}

if (typeof factura === 'string') {
  factura = JSON.parse(factura);
}

const normalizeCuit = (value) => {
  if (!value) return null;
  const digits = String(value).replace(/\D/g, '');
  return digits || null;
};

const normalizeNumber = (value) => {
  if (value === null || value === undefined || value === '') return 0;
  if (typeof value === 'number') return value;
  const normalized = String(value)
    .replace(/\$/g, '')
    .replace(/\s/g, '')
    .replace(/\./g, '')
    .replace(',', '.');
  const n = Number(normalized);
  return Number.isFinite(n) ? n : 0;
};

factura.emisor = factura.emisor || {};
factura.receptor = factura.receptor || {};
factura.periodo_facturado = factura.periodo_facturado || {};
factura.cae = factura.cae || factura.CAE || { numero: null, vencimiento: null };

factura.emisor.cuit = normalizeCuit(factura.emisor.cuit || factura.emisor.CUIT);
factura.receptor.cuit = normalizeCuit(factura.receptor.cuit || factura.receptor.CUIT);
factura.subtotal = normalizeNumber(factura.subtotal);
factura.importe_total = normalizeNumber(factura.importe_total);

if (!factura.importe_total && factura.subtotal) {
  factura.importe_total = factura.subtotal;
}

return [
  {
    json: {
      factura,
      raw_text: original.raw_text,
      pdf_url: original.pdf_url,
      safe_file_name: original.safe_file_name,
      original_file_name: original.original_file_name
    }
  }
];

const facturaData = $('Normalizar JSON IA').first().json;
const rows = $input.all().map(i => i.json);

return [
  {
    json: {
      ...facturaData,
      proveedor_cuit_results: rows,
      proveedor_cuit_found: rows.length > 0
    }
  }
];

const base = $('Merge resultado CUIT').first().json;
const nombreRows = $input.all().map(i => i.json);

return [
  {
    json: {
      ...base,
      proveedor_nombre_results: nombreRows,
      proveedor_nombre_found: nombreRows.length > 0
    }
  }
];

const data = $input.first().json;

let proveedor = null;
let matchMethod = 'not_found';

if (data.proveedor_cuit_results && data.proveedor_cuit_results.length > 0) {
  proveedor = data.proveedor_cuit_results[0];
  matchMethod = 'cuit';
} else if (data.proveedor_nombre_results && data.proveedor_nombre_results.length > 0) {
  proveedor = data.proveedor_nombre_results[0];
  matchMethod = 'nombre';
}

const proveedorEncontrado = !!proveedor;

return [
  {
    json: {
      ...data,
      proveedor_id: proveedor?.id || null,
      proveedor_match_method: matchMethod,
      proveedor_encontrado: proveedorEncontrado,
      cta_imputacion: proveedor?.cta_imputacion || null,
      validacion: proveedor?.validacion || null,
      status: proveedorEncontrado ? 'pending_review' : 'proveedor_no_encontrado'
    }
  }
];

const data = $('Resolver proveedor').first().json;
const f = data.factura || {};
const pdfUrl = $('HTTP Request6').first().json;

function sqlString(value) {
  if (value === null || value === undefined || value === '') return 'NULL';
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}
function sqlNumber(value) {
  if (value === null || value === undefined || value === '') return 0;
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}
function sqlDate(value) {
  if (!value) return 'NULL';
  return sqlString(value);
}

// --- Determinar tipo de factura (A/B/C) y el amount_bucket correspondiente ---
function getTipoFactura(f) {
  // Si en algún momento agregan el campo directo, se usa primero
  if (f.tipo_factura) return String(f.tipo_factura).toUpperCase();

  const codigo = String(f.codigo_comprobante || '').padStart(2, '0');
  const codigosA = ['01', '02', '03', '04', '05'];
  const codigosB = ['06', '07', '08', '09', '10'];
  const codigosC = ['11', '12', '13', '15'];

  if (codigosA.includes(codigo)) return 'A';
  if (codigosB.includes(codigo)) return 'B';
  if (codigosC.includes(codigo)) return 'C';
  return null;
}

const tipoFactura = getTipoFactura(f);

let amountBucket;
if (tipoFactura === 'A') {
  amountBucket = 'gravado';
} else if (tipoFactura === 'C') {
  amountBucket = 'exento';
} else {
  amountBucket = null; // B u otro caso no contemplado explícitamente
}

return [
  {
    json: {
      proveedor_id_sql: data.proveedor_id || 'NULL',
      proveedor_match_method_sql: sqlString(data.proveedor_match_method),
      proveedor_encontrado_sql: data.proveedor_encontrado ? 1 : 0,
      emisor_cuit_sql: sqlString(f.emisor?.cuit),
      emisor_nombre_sql: sqlString(f.emisor?.nombre),
      receptor_cuit_sql: sqlString(f.receptor?.cuit),
      receptor_nombre_sql: sqlString(f.receptor?.nombre),
      tipo_comprobante_sql: sqlString(tipoFactura),
      codigo_comprobante_sql: sqlString(f.codigo_comprobante),
      punto_de_venta_sql: sqlString(f.punto_de_venta),
      numero_comprobante_sql: sqlString(f.numero_comprobante),
      fecha_emision_sql: sqlDate(f.fecha_emision),
      periodo_desde_sql: sqlDate(f.periodo_facturado?.desde),
      periodo_hasta_sql: sqlDate(f.periodo_facturado?.hasta),
      fecha_vencimiento_pago_sql: sqlDate(f.fecha_vencimiento_pago),
      subtotal_sql: sqlNumber(f.subtotal),
      importe_total_sql: sqlNumber(f.importe_total),
      conceptos_sql: sqlString(f.conceptos),
      cta_imputacion_sql: sqlString(data.cta_imputacion),
      validacion_sql: sqlString(data.validacion),
      raw_text_sql: sqlString(data.raw_text),
      raw_json_sql: sqlString(JSON.stringify(f)),
      status_sql: sqlString(data.status),
      percepcion_iibb_pcia_sql: sqlNumber(f.percepcion_iibb_pcia),
      percepcion_iibb_sql: sqlNumber(f.percepcion_iibb),
      pdf_url_sql: sqlString(`https://redoo.com.ar/apis/images_upload/${pdfUrl.path.replace(/ /g, "")}`),
      error_message_sql: 'NULL',
      company_id: 95,
      amount_bucket_sql: sqlString(amountBucket),
      currency: sqlString(f.currency)
    }
  }
];

const data = $('Normalizar JSON IA').first().json;
const f = data.factura || {};

function sqlString(value) {
  if (value === null || value === undefined || value === '') return 'NULL';
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

return [
  {
    json: {
      proveedor_id_sql: 'NULL',
      proveedor_match_method_sql: sqlString('not_found'),
      proveedor_encontrado_sql: 0,
      emisor_cuit_sql: sqlString(f.emisor?.cuit),
      emisor_nombre_sql: sqlString(f.emisor?.nombre),
      receptor_cuit_sql: sqlString(f.receptor?.cuit),
      receptor_nombre_sql: sqlString(f.receptor?.nombre),
      tipo_comprobante_sql: sqlString(f.tipo_comprobante),
      codigo_comprobante_sql: sqlString(f.codigo_comprobante),
      punto_de_venta_sql: sqlString(f.punto_de_venta),
      numero_comprobante_sql: sqlString(f.numero_comprobante),
      fecha_emision_sql: f.fecha_emision ? sqlString(f.fecha_emision) : 'NULL',
      periodo_desde_sql: f.periodo_facturado?.desde ? sqlString(f.periodo_facturado.desde) : 'NULL',
      periodo_hasta_sql: f.periodo_facturado?.hasta ? sqlString(f.periodo_facturado.hasta) : 'NULL',
      fecha_vencimiento_pago_sql: f.fecha_vencimiento_pago ? sqlString(f.fecha_vencimiento_pago) : 'NULL',
      subtotal_sql: Number(f.subtotal || 0),
      importe_total_sql: Number(f.importe_total || 0),
      conceptos_sql: sqlString(f.conceptos),
      cta_imputacion_sql: 'NULL',
      validacion_sql: 'NULL',
      pdf_url_sql: sqlString(data.pdf_url),
      raw_text_sql: sqlString(data.raw_text),
      raw_json_sql: sqlString(JSON.stringify(f)),
      status_sql: sqlString('invalid_invoice'),
      error_message_sql: sqlString('El archivo no parece una factura valida o no tiene numero de comprobante')
    }
  }
];

const file = $('Loop PDFs').first().binary;

return [{
  binary: file
}];
